/* CSS PART 1 OF 2 */

/* Design tokens */
:root {
  --forest: #243d32;
  --forest-deep: #172b23;
  --sage: #84977a;
  --sage-light: #e8ede3;
  --earth: #b77c50;
  --cream: #f7f5ee;
  --paper: #fffefa;
  --ink: #28332d;
  --muted: #69746b;
  --line: #dce1d7;
  --white: #ffffff;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --radius: 4px;
  --shadow: 0 14px 40px rgba(23, 43, 35, 0.10);
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: var(--sage-light);
  color: var(--forest-deep);
}

:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

/* Shared typography */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--forest);
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 1.12;
}

h1 {
  max-width: 850px;
  margin-bottom: 25px;
  font-size: clamp(3rem, 7.2vw, 6.5rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.3rem, 4.5vw, 4rem);
}

h3 {
  margin-bottom: 12px;
  font-size: clamp(1.45rem, 2.2vw, 1.9rem);
}

p {
  color: var(--muted);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--forest);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 27px;
  height: 1px;
  background: var(--earth);
  content: "";
}

.section-intro {
  max-width: 640px;
  margin-bottom: 48px;
  font-size: 1.08rem;
  line-height: 1.85;
}

.section-heading {
  max-width: 700px;
  margin-bottom: 24px;
}

.section-heading h2 {
  margin-bottom: 16px;
}

/* Page structure */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 10vw, 138px);
}

.section--soft {
  background: var(--cream);
}

.section--dark {
  background: var(--forest);
  color: var(--white);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.76);
}

.section-kicker {
  display: block;
  margin-bottom: 15px;
  color: var(--earth);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid rgba(36, 61, 50, 0.10);
}

.header-inner {
  display: flex;
  min-height: 92px;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
  color: var(--forest);
}

.brand img {
  width: 54px;
  height: 54px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.35rem;
  letter-spacing: -0.035em;
}

.brand-caption {
  margin-top: 5px;
  color: var(--muted);
  font-size: 0.61rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.6vw, 35px);
}

.primary-nav a {
  position: relative;
  padding-block: 10px;
  color: var(--forest);
  font-size: 0.83rem;
  font-weight: 600;
  transition: color 180ms ease;
}

.primary-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 4px;
  left: 0;
  height: 1px;
  background: var(--earth);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 180ms ease;
}

.primary-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* Buttons */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.045em;
  text-align: center;
  transition:
    background 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  background: var(--forest-deep);
  transform: translateY(-2px);
}

.button--light {
  background: var(--paper);
  color: var(--forest);
}

.button--light:hover {
  background: var(--sage-light);
  color: var(--forest-deep);
}

.button--outline {
  border-color: rgba(36, 61, 50, 0.45);
  background: transparent;
  color: var(--forest);
}

.button--outline:hover {
  border-color: var(--forest);
  background: var(--forest);
  color: var(--white);
}

.button-arrow {
  font-size: 1.1rem;
  line-height: 1;
}

/* Full-width hero */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 92px));
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 39, 29, 0.86) 0%,
      rgba(18, 39, 29, 0.64) 44%,
      rgba(18, 39, 29, 0.12) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 39, 29, 0.30),
      transparent 55%
    );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 1;
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
  padding-block: 100px;
}

.hero .eyebrow {
  color: #e4c6a7;
}

.hero h1 {
  max-width: 800px;
  color: var(--white);
}

.hero-description {
  max-width: 560px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1rem, 1.5vw, 1.17rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  margin-top: 25px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.77rem;
  letter-spacing: 0.04em;
}

/* Landscape design and installation */
.design-section {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: center;
  gap: clamp(44px, 8vw, 108px);
}

.design-copy {
  max-width: 540px;
}

.design-copy p {
  font-size: 1.02rem;
  line-height: 1.9;
}

.design-visual {
  position: relative;
  min-height: 450px;
  background: var(--sage-light);
}

.design-visual img {
  width: 100%;
  height: 100%;
  min-height: 450px;
  object-fit: cover;
}

.design-caption {
  position: absolute;
  right: -18px;
  bottom: 25px;
  max-width: 220px;
  padding: 20px 24px;
  background: var(--paper);
  box-shadow: var(--shadow);
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.35;
}

/* Year-round maintenance */
.maintenance-section {
  position: relative;
  overflow: hidden;
}

.maintenance-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 9vw, 120px);
}

.maintenance-copy {
  max-width: 460px;
}

.maintenance-copy p {
  font-size: 1.03rem;
  line-height: 1.9;
}

.maintenance-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 36px;
  border-top: 1px solid var(--line);
}

.maintenance-item {
  padding-block: 25px;
  border-bottom: 1px solid var(--line);
}

.maintenance-item h3 {
  margin-bottom: 8px;
  font-size: 1.35rem;
}

.maintenance-item p {
  margin-bottom: 0;
  font-size: 0.91rem;
  line-height: 1.7;
}

/* Irrigation, patios, raised beds and fences */
.services-section {
  background: var(--cream);
}

.services-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 50px;
}

.services-heading .section-heading {
  margin-bottom: 0;
}

.services-heading > p {
  max-width: 340px;
  margin-bottom: 7px;
}

.services-list {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.service-item {
  min-height: 190px;
  padding: 30px 24px 32px 0;
  border-right: 1px solid var(--line);
}

.service-item + .service-item {
  padding-left: 24px;
}

.service-item:last-child {
  border-right: 0;
}

.service-number {
  display: block;
  margin-bottom: 30px;
  color: var(--earth);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.service-item h3 {
  margin-bottom: 10px;
  font-size: 1.45rem;
}

.service-item p {
  margin-bottom: 0;
  font-size: 0.88rem;
  line-height: 1.7;
}

/* Family-owned service and local sourcing */
.local-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 100px);
}

.local-copy {
  max-width: 540px;
}

.local-copy p {
  font-size: 1.02rem;
  line-height: 1.9;
}

.local-note {
  margin-top: 28px;
  padding: 22px 24px;
  border-left: 3px solid var(--earth);
  background: var(--sage-light);
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.5;
}

.local-visual {
  min-height: 410px;
  background: var(--sage-light);
}

.local-visual img {
  width: 100%;
  height: 100%;
  min-height: 410px;
  object-fit: cover;
}
