/* CSS PART 2 OF 2 */

/* Contact and conversion area */
.contact-section {
  padding-block: clamp(76px, 9vw, 120px);
  background: var(--forest);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 100px);
}

.contact-copy {
  max-width: 470px;
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy p {
  color: rgba(255, 255, 255, 0.78);
  line-height: 1.85;
}

.contact-copy .eyebrow {
  color: #e4c6a7;
}

.contact-promise {
  margin-top: 32px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.25);
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.9rem;
}

.contact-form {
  padding: clamp(24px, 4vw, 42px);
  background: var(--paper);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 28px;
  color: var(--forest);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: 0.78rem;
  font-weight: 700;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-width: 0;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: var(--white);
  color: var(--ink);
  font-size: 0.94rem;
  transition: border-color 160ms ease;
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--forest);
  outline: 2px solid var(--sage);
  outline-offset: 2px;
}

.form-submit {
  margin-top: 24px;
}

.form-disclaimer {
  margin: 15px 0 0;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.6;
}

/* Footer */
.site-footer {
  padding-block: 45px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.footer-brand {
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.3rem;
}

.footer-copy {
  margin: 7px 0 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.78rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.8rem;
}

.footer-nav a:hover {
  color: var(--white);
}

/* Accessible mobile navigation control */
.menu-button {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-button span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Responsive layouts */
@media (max-width: 900px) {
  :root {
    --gutter: 30px;
  }

  .header-inner {
    min-height: 78px;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a {
    font-size: 0.76rem;
  }

  .hero {
    min-height: 650px;
  }

  .design-section,
  .local-section {
    grid-template-columns: 1fr 1fr;
    gap: 35px;
  }

  .maintenance-layout {
    grid-template-columns: 1fr 1.3fr;
    gap: 35px;
  }

  .services-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .service-item:nth-child(2) {
    border-right: 0;
  }

  .service-item:nth-child(n+3) {
    border-top: 1px solid var(--line);
  }

  .service-item:nth-child(3) {
    padding-left: 0;
  }

  .contact-layout {
    grid-template-columns: 1fr 1.2fr;
    gap: 35px;
  }
}

@media (max-width: 680px) {
  :root {
    --gutter: 22px;
  }

  html {
    scroll-padding-top: 75px;
  }

  body {
    font-size: 15px;
  }

  .section {
    padding-block: 76px;
  }

  .header-inner {
    min-height: 72px;
    gap: 12px;
  }

  .brand {
    gap: 9px;
  }

  .brand img {
    width: 44px;
    height: 44px;
  }

  .brand-name {
    font-size: 1.17rem;
  }

  .brand-caption {
    font-size: 0.55rem;
  }

  .menu-button {
    display: flex;
  }

  /* Desktop link row stays hidden; an accessible toggle controls this menu. */
  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    z-index: 30;
    max-height: calc(100svh - 72px);
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 12px var(--gutter) 22px;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    background: var(--paper);
    box-shadow: 0 14px 24px rgba(23, 43, 35, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a {
    display: block;
    width: 100%;
    padding: 14px 4px;
    font-size: 0.9rem;
    overflow-wrap: anywhere;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 8px;
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - 72px));
    align-items: end;
  }

  .hero-media {
    object-position: 58% center;
  }

  .hero::after {
    background:
      linear-gradient(
        0deg,
        rgba(18, 39, 29, 0.92) 0%,
        rgba(18, 39, 29, 0.70) 48%,
        rgba(18, 39, 29, 0.18) 100%
      );
  }

  .hero-content {
    padding-block: 100px 66px;
  }

  h1 {
    font-size: clamp(2.8rem, 12vw, 4.6rem);
  }

  h2 {
    font-size: clamp(2.25rem, 9vw, 3.3rem);
  }

  .hero-description {
    font-size: 0.98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .design-section,
  .local-section,
  .maintenance-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .design-visual,
  .design-visual img {
    min-height: 320px;
  }

  .design-caption {
    right: 12px;
    bottom: 12px;
    max-width: 190px;
    padding: 15px 18px;
    font-size: 1.05rem;
  }

  .maintenance-details {
    grid-template-columns: 1fr;
  }

  .maintenance-item {
    padding-block: 20px;
  }

  .services-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .services-list {
    grid-template-columns: 1fr;
  }

  .service-item,
  .service-item + .service-item {
    min-height: 0;
    padding: 23px 0;
    border-right: 0;
    border-top: 1px solid var(--line);
  }

  .service-item:first-child {
    border-top: 0;
  }

  .service-number {
    margin-bottom: 15px;
  }

  .local-visual,
  .local-visual img {
    min-height: 300px;
  }

  .contact-section {
    padding-block: 76px;
  }

  .contact-form {
    padding: 24px 19px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field--full {
    grid-column: auto;
  }

  .form-submit,
  .form-submit .button {
    width: 100%;
  }

  .footer-inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 24px;
  }

  .footer-nav {
    gap: 12px 22px;
  }
}

@media (max-width: 380px) {
  :root {
    --gutter: 17px;
  }

  .brand-name {
    font-size: 1.05rem;
  }

  .brand-caption {
    font-size: 0.5rem;
  }

  .hero-content {
    padding-block: 75px 48px;
  }

  .contact-form {
    padding: 20px 15px;
  }
}

/* Visible keyboard focus */
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

.menu-button:focus-visible {
  outline-color: var(--earth);
  outline-offset: 4px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
